values
('eac-burundi-constitution','Burundi Constitution — Presidency / Constitutional Court','Presidency of the Republic of Burundi','constitution_catalog','BI','https://presidence.gov.bi/2018/07/6271-2/','https://courconstitutionnelle.gov.bi/','https://presidence.gov.bi/2018/07/6271-2/',1,true,'review_required',false,'Official 2018 constitutional text and Constitutional Court fundamental-texts directory. Confirm subsequent amendments and current consolidation before import.',null,false,'{"region":"EAC","candidateText":"Constitution promulgated 7 June 2018","secondOfficialSourceUrl":"https://courconstitutionnelle.gov.bi/","currentVersionVerified":false,"rightsReview":"required"}'::jsonb),
('eac-drc-constitution','DR Congo Constitution — Cour de Cassation','Cour de Cassation, Democratic Republic of the Congo','constitution_catalog','CD','https://cassation.cd/textes-legaux/constitution-rdc',null,'https://cassation.cd/textes-legaux/constitution-rdc',1,true,'review_required',false,'Official court-hosted Constitution of 18 February 2006 as modified by Law No. 11/002 of 20 January 2011. Verify later amendments and Journal Officiel.',null,false,'{"region":"EAC","candidateText":"Constitution of 18 February 2006, modified 20 January 2011","currentVersionVerified":false,"rightsReview":"required"}'::jsonb),
('kenya-law','Kenya Constitution — National Council for Law Reporting / Kenya Law','National Council for Law Reporting','legislation_portal','KE','https://new.kenyalaw.org/legislation/',null,'https://kenyalaw.org/terms-of-use/',1,true,'review_required',false,'Official Constitution and consolidated laws. Metadata/link-only until a written NCLR licence expressly covers automated extraction, commercial reuse and AI/LLM retrieval.',null,false,'{"region":"EAC","rightsEvidenceUrl":"https://kenyalaw.org/terms-of-use/","rightsNotes":"NCLR terms prohibit automated bulk extraction, commercial redistribution and AI/ML training without an explicit Licensing Agreement. No full-text import or AI retrieval until a written licence covers the exact text, language and processing use.","archiveReference":"https://presidentiallibrary.go.ke/documents/constitution-kenya-2010","currentVersionVerified":false,"rightsReview":"written_nclr_licence_required"}'::jsonb),
('rwanda-minijust','Rwanda Constitution — Ministry of Justice / Official Gazette','Ministry of Justice, Republic of Rwanda','constitution_catalog','RW','https://www.minijust.gov.rw/fileadmin/user_upload/Minijust/Publications/Laws/Constitution.pdf',null,'https://www.minijust.gov.rw/fileadmin/user_upload/Minijust/Publications/Laws/Constitution.pdf',1,true,'review_required',false,'Official Gazette special issue of 4 August 2023, revised Constitution of 2003 as amended in 2015 and 2023. Confirm later changes and rights before import.',null,false,'{"region":"EAC","secondOfficialSourceUrl":"https://www.parliament.gov.rw/fileadmin/user_upload/The_Constitution_of_the_Republic_of_Rwanda.pdf","gazetteDate":"2023-08-04","currentVersionVerified":false,"rightsReview":"required"}'::jsonb),
('eac-somalia-constitution','Somalia Federal Constitution — Ministry of Interior / Federal Affairs','Ministry of Interior, Federal Affairs & Reconciliation, Federal Republic of Somalia','constitution_catalog','SO','https://moifar.gov.so/en/page/federal-constitution',null,'https://moifar.gov.so/en/page/federal-constitution',1,true,'review_required',false,'Official government constitution index. Hold publication pending reconciliation of the 2026 Constitution claims with official material describing amendments to the 2012 Provisional Constitution.',null,false,'{"region":"EAC","versionConflict":true,"versionCrossCheckUrls":["https://villasomalia.gov.so/constitution-2/","https://opm.gov.so/en/policies/amendments-to-the-provisional-constitution-of-the-federal-republic-of-somalia-chapters-1-4"],"currentVersionVerified":false,"rightsReview":"required","legalReview":"required_before_version_selection"}'::jsonb),
('eac-south-sudan-constitution','South Sudan Transitional Constitution — Ministry of Justice','Ministry of Justice and Constitutional Affairs, Republic of South Sudan','constitution_catalog','SS','https://mojca.gov.ss/the-transitional-constitution-of-the-repulic-of-south-sudan/',null,'https://mojca.gov.ss/constitution-and-government/',1,true,'review_required',false,'Official Ministry page for the Transitional Constitution of 2011. Obtain and verify the latest consolidated amendments and effective dates before import.',null,false,'{"region":"EAC","currentVersionVerified":false,"rightsReview":"required"}'::jsonb),
