('uganda-parliament','Uganda Constitution — Uganda Law Reform Commission','Uganda Law Reform Commission','constitution_catalog','UG','https://publications.ulrc.go.ug/constitution/29',null,'https://publications.ulrc.go.ug/constitution/29',1,true,'review_required',false,'Official ULRC record for the updated Constitution of 1995; the publication is marked subscription access. Verify the latest consolidated text, amendments and rights terms before import.',null,false,'{"region":"EAC","accessType":"subscription","crossCheckUrl":"https://ulii.org/en/akn/ug/act/statute/1995/constitution/eng%402023-12-31","secondOfficialSourceUrl":"https://statehouse.go.ug/the-constitution/","currentVersionVerified":false,"rightsReview":"required"}'::jsonb)
